#include <string>
#include <vector>
#include <cstring>

class Solution {
    long long memo[20][11][2][2];
    std::string s;
    long long solve(int idx, int last, bool isLess, bool started) {
        if (idx == (int)s.length()) return started ? 1 : 0;
        int lIdx = last == -1 ? 10 : last;
        if (memo[idx][lIdx][isLess][started] != -1) return memo[idx][lIdx][isLess][started];
        int limit = isLess ? 9 : (s[idx] - '0');
        long long ans = 0;
        for (int d = 0; d <= limit; ++d) {
            if (!started && d == 0) {
                ans += solve(idx + 1, -1, isLess || (d < limit), false);
            } else {
                if (d != last) {
                    ans += solve(idx + 1, d, isLess || (d < limit), true);
                }
            }
        }
        return memo[idx][lIdx][isLess][started] = ans;
    }
    long long countUpTo(long long n) {
        if (n < 0) return 0;
        s = std::to_string(n);
        std::memset(memo, -1, sizeof(memo));
        return solve(0, -1, false, false);
    }
public:
    long long countFancy(long long low, long long high) {
        return countUpTo(high) - countUpTo(low - 1);
    }
};

import java.util.*;

class Solution {
    private Long[][][][] memo;
    private String s;

    private long solve(int idx, int last, boolean isLess, boolean started) {
        if (idx == s.length()) return started ? 1 : 0;
        int lIdx = last == -1 ? 10 : last;
        int lessIdx = isLess ? 1 : 0;
        int startIdx = started ? 1 : 0;
        if (memo[idx][lIdx][lessIdx][startIdx] != null) return memo[idx][lIdx][lessIdx][startIdx];
        int limit = isLess ? 9 : (s.charAt(idx) - '0');
        long ans = 0;
        for (int d = 0; d <= limit; d++) {
            if (!started && d == 0) {
                ans += solve(idx + 1, -1, isLess || (d < limit), false);
            } else {
                if (d != last) {
                    ans += solve(idx + 1, d, isLess || (d < limit), true);
                }
            }
        }
        return memo[idx][lIdx][lessIdx][startIdx] = ans;
    }

    private long countUpTo(long n) {
        if (n < 0) return 0;
        s = String.valueOf(n);
        memo = new Long[s.length()][11][2][2];
        return solve(0, -1, false, false);
    }

    public long countFancy(long low, long high) {
        return countUpTo(high) - countUpTo(low - 1);
    }
}

function countFancy(low, high) {
    const countUpTo = (n) => {
        if (n < 0) return 0;
        const s = String(n);
        const m = s.length;
        const memo = new Map();
        const dp = (idx, last, isLess, started) => {
            if (idx === m) return started ? 1 : 0;
            const key = `${idx},${last},${isLess},${started}`;
            if (memo.has(key)) return memo.get(key);
            const limit = isLess ? 9 : Number(s[idx]);
            let ans = 0;
            for (let d = 0; d <= limit; d++) {
                if (!started && d === 0) {
                    ans += dp(idx + 1, -1, isLess || (d < limit), false);
                } else {
                    if (d !== last) {
                        ans += dp(idx + 1, d, isLess || (d < limit), true);
                    }
                }
            }
            memo.set(key, ans);
            return ans;
        };
        return dp(0, -1, false, false);
    };
    return countUpTo(high) - countUpTo(low - 1);
}
